import React, { Component } from 'react'
import { connect } from 'react-redux'
import { withRouter } from 'react-router'
import { Card, Steps, Icon, Divider, notification, Spin } from 'antd'

import { AddConfigStyle } from './index.style'
import ChooseTemplate from '../../Onboarding/AddConfig/chooseTemplate'
import Questionnaire from '../../Onboarding/AddConfig/questionnaire'
import Review from '../../Onboarding/AddConfig/review'
import ClaimsAction from '../../../../redux/claims/actions'
import LoadingActions from '../../../../../redux/loading/actions'
import ErrorActions from '../../../../../redux/error/actions'
import { findAndReplaceKey } from '../../Onboarding/AddConfig/helpers'

const { Step } = Steps

const {
  getInprogressConfig,
  getPolicyFormAttributes,
  updateClaimConfigData,
  getPolicyFormAttributesMultipleProduct,
  resetReduxStateClaim
} = ClaimsAction
const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions

const CONFIGSTATES = {
  ADD: 'ADD',
  EDIT: 'EDIT',
  INPROGRESS: 'INPROGRESS'
}

class AddConfig extends Component {
  constructor (props) {
    super(props)
    this.state = {
      stepsConfig: [
        { title: 'Choose Template', status: 'process', icon: 'container' },
        { title: 'Questionnaire', status: 'wait', icon: 'control' },
        { title: 'Review', status: 'wait', icon: 'check-circle' }
      ],
      current: 0,
      benefitId: '',
      configData: [],
      inprogressConfig: undefined,
      configSlug: undefined,
      configState: CONFIGSTATES.ADD,
      editData: undefined,
      questions: undefined,
      responsesProvided: undefined,
      source: props.location.pathname.includes('green') ? 'green_channel' : 'auto_approval'
    }
  }

  componentDidMount () {
    const { productKey, benefitId, configDumpData = {}, configData, getPolicyFormAttributesMultipleProduct } = this.props

    const { responses_provided: responsesProvided, questions } = configDumpData

    if (configDumpData && Object.keys(configDumpData).length) {
      this.setState({
        configState: CONFIGSTATES.EDIT,
        configData: questions,
        configDumpId: configData.config_dump_id,
        autoApprovalConfigId: configData.config_id,
        responsesProvided: responsesProvided,
        questions
      })
      this.handleEditConfigData(configDumpData)
    }
    this.setState({ benefitId })
    const neededProductKey = productKey && productKey.length && productKey.map((val) => val.name).join(',')
    getPolicyFormAttributesMultipleProduct({
      query: {
        product_keys: neededProductKey
      }
    })
  }

  componentDidUpdate (prevProps) {
    const { productKey, getPolicyFormAttributesMultipleProduct } = this.props
    const { productKey: prevProductKey } = prevProps

    if (productKey !== prevProductKey) {
      const neededProductKey = productKey && productKey.length && productKey.map((val) => val.name).join(',')
      getPolicyFormAttributesMultipleProduct({
        query: {
          product_keys: neededProductKey
        }
      })
    }
  }

  componentWillUnmount () {
    const { resetReduxStateClaim } = this.props

    if (resetReduxStateClaim) {
      resetReduxStateClaim(['inprogressConfig', 'claimsConfigTemplatesDetails', 'claimConfigData'])
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      inprogressConfigLoading,
      inprogressConfigError,
      inprogressConfigStatus
    } = nextProps

    if (inprogressConfigLoading === false) {
      if (inprogressConfigError) {
        notification.error({ message: inprogressConfigStatus })
      }
      this.props.resetErrorRedux(['GET_INPROGRESS_CONFIG'])
      this.props.resetLoadingRedux(['GET_INPROGRESS_CONFIG'])
    }
  }

  handleStepChange = (step) => {
    const { stepsConfig } = this.state
    const tempStepsConfig = stepsConfig
    for (let i = 0; i < step; i++) {
      tempStepsConfig[i].status = 'finish'
    }
    tempStepsConfig[step].status = 'process'
    this.setState({ current: step, stepsConfig: tempStepsConfig })
  }

  handleEditConfigData = () => {
    const { configDumpData } = this.props
    const { responses_provided: responsesProvided, questions } = configDumpData

    const formData = responsesProvided

    this.setState({
      formData: formData,
      configData: responsesProvided
    })

    responsesProvided && Object.keys(responsesProvided).forEach((key) => {
      if (responsesProvided[key].is_valid) {
        delete responsesProvided[key].is_valid
      }
    })

    responsesProvided && Object.keys(responsesProvided).forEach((response, index) => {
      Object.keys(responsesProvided[response]).map((label) => findAndReplaceKey(questions[index], 'name', label, 'default_answer', responsesProvided[response][label]))
    })
    this.setState({ questions, responsesProvided })
  }

  onHandleNext = () => {
    const { stepChangeInTemplate } = this.props
    const { current, stepsConfig } = this.state
    const tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = 'finish'
    tempStepsConfig[current + 1].status = 'process'
    this.setState({ current: current + 1, stepsConfig: tempStepsConfig })
    stepChangeInTemplate(current + 1)
  }

  onHandlePrevious = () => {
    const { current, stepsConfig } = this.state
    const tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = 'wait'
    tempStepsConfig[current - 1].status = 'process'
    this.setState({ current: current - 1, stepsConfig: tempStepsConfig })
  }

  saveQuestionnaireData = (data) => {
    this.setState({ configData: data })
  }

  saveResponse = (data, formData) => {
    this.setState({ configData: data, formData })
  }

  getQuestions = () => {
    const { claimsConfigTemplatesDetails = {} } = this.props
    const { configState, questions: stateQuestions } = this.state
    const { questions = [] } = claimsConfigTemplatesDetails

    switch (configState) {
      case CONFIGSTATES.INPROGRESS:
      case CONFIGSTATES.EDIT:
        return stateQuestions
      default:
        return questions
    }
  }

  render () {
    const { history, inprogressConfigLoading, productKey, provider, benefitId } = this.props
    const {
      stepsConfig, current, configData, formData,
      inprogressConfig, configDumpId, configSlug, editData, configState, responsesProvided, autoApprovalConfigId,
      source
    } = this.state

    return (
      <AddConfigStyle>
        <Spin spinning={!!inprogressConfigLoading}>
          <Card>
            <div className='heading'>
              Wizard
            </div>
            <Steps current={current}>
              {
                stepsConfig.map(({ title, status, icon }, index) =>
                  <Step key={index} title={title} status={status} icon={<Icon type={icon} />} />
                )
              }
            </Steps>
            {
              current === 0 &&
                <Card>
                  <ChooseTemplate
                    configSource='auto_approval'
                    handleNext={this.onHandleNext}
                    handleInprogressConfigData={this.onHandleInprogressConfigData}
                    edit={configState === CONFIGSTATES.EDIT}
                  />
                </Card>
            }
            {
              current === 1 &&
                <Card>
                  <Questionnaire
                    benefitId={benefitId}
                    saveQuestionnaireData={this.saveQuestionnaireData}
                    handleNext={this.onHandleNext}
                    handlePrevious={this.onHandlePrevious}
                    configData={configData}
                    questions={this.getQuestions()}
                    inprogess={inprogressConfig}
                    configDumpId={configDumpId}
                    editData={editData}
                    configState={configState}
                    responsesProvided={responsesProvided}
                    inprogressConfig={inprogressConfig}
                    hideBackToFormButton={false}
                    source={source}
                  />
                </Card>
            }
            {
              current === 2 &&
                <Card>
                  <Review
                    configData={configData}
                    formData={formData}
                    history={history}
                    configSlug={configSlug}
                    configDumpId={configDumpId}
                    handlePrevious={this.onHandlePrevious}
                    inprogressConfig={inprogressConfig}
                    partnerProductKey={productKey}
                    providerId={provider}
                    autoApprovalConfigId={autoApprovalConfigId}
                    benefitId={benefitId}
                    source={source}
                  />
                </Card>
            }
            <Divider />
          </Card>
        </Spin>
      </AddConfigStyle>
    )
  }
}

export default withRouter(connect(state => ({
  inprogressConfigLoading: state.Loading.GET_INPROGRESS_CONFIG,
  inprogressConfigError: state.Error.GET_INPROGRESS_CONFIG,
  inprogressConfig: state.Claims.inprogressConfig,
  inprogressConfigStatus: state.Claims.inprogressConfigStatus,
  claimsConfigTemplatesDetails: state.Claims.claimsConfigTemplatesDetails,
  claimConfigData: state.Claims.claimConfigData
}), {
  getInprogressConfig,
  getPolicyFormAttributes,
  updateClaimConfigData,
  resetLoadingRedux,
  resetErrorRedux,
  resetReduxStateClaim,
  getPolicyFormAttributesMultipleProduct
})(AddConfig))
