import { useState, useEffect, useMemo } from 'react'
import { connect } from 'react-redux'
import { Form, Button, Select, Spin } from 'antd'
import { useLocation } from 'react-router'

import AddConfig from './AddConfig'

import PolicyActions from '../../../../../redux/policy/actions'
import ClaimActions from '../../../../redux/claims/actions'
import providerAction from '../../../../redux/provider/actions'

import { FormContainer } from './index.style'

const { getProducts } = PolicyActions
const { getProviderList } = providerAction
const {
  getConfigTemplates,
  resetReduxStateClaim,
  getAutoApprovalConfigInfo,
  getGreenChannelData,
  getPackageMultipleProduct,
  getMultipleProductBenefitList,
  getPolicyFormAttributesMultipleProduct
} = ClaimActions

const { Option, OptGroup } = Select

function useQuery () {
  const { search } = useLocation()

  return useMemo(() => new URLSearchParams(search), [search])
}

function AddInstantClaimConfiguration (props) {
  const {
    form,
    productList,
    getProducts,
    packageList,
    providerList,
    getProviderList,
    benefitGroupData,
    providerListError,
    getConfigTemplates,
    claimConfigTemplate,
    providerListLoading,
    getGreenChannelData,
    resetReduxStateClaim,
    getPackageListLoading,
    greenChannelConfigData,
    getBenefitGroupLoading,
    autoApprovalConfigData,
    getPackageMultipleProduct,
    getAutoApprovalConfigInfo,
    getMultipleProductBenefitList,
    autoApprovalConfigDataLoading
  } = props

  const location = useLocation()

  const configData = Object.keys(autoApprovalConfigData).length ? autoApprovalConfigData.auto_approval_configs : greenChannelConfigData

  const source = useMemo(() => {
    if (location.pathname.includes('green')) return 'green_channel'
    return 'auto_approval'
  }, [
    location
  ])

  const { getFieldDecorator, getFieldError, isFieldTouched } = form

  const [selectedProvider, setSelectedProvider] = useState(undefined)
  const [selectedProduct, setSelectedProduct] = useState(undefined)
  const [selectedBenefit, setSelectedBenefit] = useState(undefined)
  const [currentStepInConfig, setCurrentStepInConfig] = useState(0)

  const query = useQuery()
  const configId = query.get('configId')

  const existingBenefits = configData.benefits
  const configDumpData = configData.config_dump_data

  useEffect(() => {
    getProducts()
    getProviderList()
  }, [getProducts, getProviderList])

  useEffect(() => {
    return () => {
      setSelectedBenefit(undefined)
      setSelectedProduct(undefined)
      setSelectedBenefit(undefined)
      resetReduxStateClaim([
        'claimConfigTemplate',
        'autoApprovalConfigData',
        'greenChannelConfigData'
      ])
    }
  }, [])

  useEffect(() => {
    if (packageList) {
      const modiFiedPackageList = {}
      for (const key in packageList) {
        const list = packageList[key].map((packageObject) => packageObject?.package_code)
        const newKey = key.slice(key.indexOf('-') + 1)
        modiFiedPackageList[newKey] = list
      }
      if (source === 'auto_approval') {
        modiFiedPackageList.exclude_auto_claim_amount = true
      }

      getMultipleProductBenefitList({ body: modiFiedPackageList })
    }
  }, [packageList, getMultipleProductBenefitList])

  useEffect(() => {
    if (selectedProduct && selectedProvider && selectedBenefit) {
      getConfigTemplates({ query: { source } })
    } else {
      resetReduxStateClaim(['claimConfigTemplate'])
    }
  }, [selectedBenefit, selectedProduct, getConfigTemplates, selectedProvider, resetReduxStateClaim])

  useEffect(() => {
    if (configId) {
      if (source === 'auto_approval') {
        const query = {
          auto_approval_config_id: configId
        }
        getAutoApprovalConfigInfo({ query })
        return
      }

      if (source === 'green_channel') {
        const query = {
          custom_config_id: configId,
          source
        }
        getGreenChannelData({ query })
      }
    }
  }, [configId, getAutoApprovalConfigInfo, getGreenChannelData])

  useEffect(() => {
    const configs = autoApprovalConfigData.auto_approval_configs || configData
    if (configs) {
      const { insurance_provider: insuranceProvider, partner_product_key: partnerProductKey } = configs

      if (insuranceProvider && providerList && providerList.length) {
        const neededProvider = providerList.find((provider) => provider.code === insuranceProvider)
        setSelectedProvider(neededProvider || insuranceProvider)
      }

      if (partnerProductKey && productList && productList.length) {
        const neededPartnerProductKey = partnerProductKey.map((partnerProduct) => {
          return productList.find((product) => {
            return `${product.partner}-${product.name}` === partnerProduct
          }) || partnerProduct
        })
        setSelectedProduct(neededPartnerProductKey)
      }
    }
  }, [providerList, productList, autoApprovalConfigData, configData])

  useEffect(() => {
    if (Array.isArray(selectedProduct) && selectedProduct.length) {
      const query = {
        partner_product_key: selectedProduct.map((product) => `${product.partner}-${product.name}`).join(',')
      }
      getPackageMultipleProduct({ query })
    } else {
      resetReduxStateClaim(['packageListOnMultipleProduct', 'benefitGroupData'])
      form.setFieldsValue({ benefit: undefined })
    }
  }, [selectedProduct, getPackageMultipleProduct])

  useEffect(() => {
    const selectedBenefit = []
    if (benefitGroupData && Object.keys(benefitGroupData).length && existingBenefits?.length) {
      for (const key in benefitGroupData) {
        if (Array.isArray(benefitGroupData[key])) {
          benefitGroupData[key].forEach((pack) => {
            const { benefits = [] } = pack
            benefits.forEach((benefit) => {
              if (existingBenefits.includes(benefit.id)) {
                selectedBenefit.push((benefit))
              }
            })
          })
        }
      }
      form.setFieldsValue({
        benefit: selectedBenefit ? selectedBenefit.map((benefit) => JSON.stringify(benefit)) : undefined
      })
      setSelectedBenefit(selectedBenefit)
    }
  }, [existingBenefits, benefitGroupData])

  useEffect(() => {
    return () => {
      resetReduxStateClaim([
        'products',
        'packageList',
        'providerList',
        'claimConfigData',
        'benefitGroupData',
        'claimConfigTemplate',
        'autoApprovalConfigData',
        'packageListOnMultipleProduct',
        'claimsConfigTemplatesDetails'
      ])
    }
  }, [resetReduxStateClaim])

  const productError = isFieldTouched('product') && getFieldError('product')
  const packageError = isFieldTouched('package') && getFieldError('package')

  const handleReset = () => {
    form.setFieldsValue({
      provider: configId ? JSON.stringify(selectedProvider) : undefined,
      product: undefined,
      benefit: undefined
    })
    setSelectedProvider(configId ? selectedProvider : undefined)
    setSelectedProduct(undefined)
    setSelectedBenefit(undefined)
    resetReduxStateClaim([
      'claimsConfigTemplatesDetails',
      'claimConfigTemplate',
      'claimConfigData',
      'benefitGroupData',
      'packageList',
      'providerList',
      'autoApprovalConfigData',
      'packageListOnMultipleProduct'
    ])
  }

  const handleSelectProduct = (list) => {
    if (!list) {
      return handleReset()
    }
    const productKeyList = list.map((value) => {
      const product = JSON.parse(value)
      return product
    })
    setSelectedProduct(productKeyList.length > 0 ? productKeyList : undefined)
    setSelectedBenefit(undefined)
  }

  const handleBenefitChange = (list) => {
    if (!list) {
      return handleReset()
    }
    const benefitSelected = list.map((value) => {
      const benefit = JSON.parse(value)
      return benefit
    })
    setSelectedBenefit(benefitSelected.length > 0 ? benefitSelected : undefined)
  }

  const handleSelectProvider = (e) => {
    let data = null
    if (e) {
      data = JSON.parse(e)
    }
    setSelectedProvider(data || undefined)
  }

  const onSelectAllClicked = () => {
    let allBenefit = []
    if (benefitGroupData) {
      allBenefit = Object.keys(benefitGroupData).map((key) => {
        const options = benefitGroupData[key].map((pack) => pack.benefits)

        return options
      }).flat(2)
    }

    form.setFieldsValue({ benefit: allBenefit.map((b) => JSON.stringify(b)) })
    setSelectedBenefit(allBenefit)
  }

  const stepChangeInTemplate = (current) => {
    setCurrentStepInConfig(current)
  }

  const getBenfitListMultiple = () => {
    const benefitListInMultilevel = []
    if (benefitGroupData && Object.keys(benefitGroupData).length) {
      for (const key in benefitGroupData) {
        const productBenefit = benefitGroupData[key]
        if (Array.isArray(productBenefit)) {
          productBenefit.forEach((benefit) => {
            const { benefits, package_code: packageCode, slug } = benefit
            const options = benefits.map((b) => {
              return {
                label: b.name,
                isActive: b.is_active,
                value: JSON.stringify(b)
              }
            }).filter(({ isActive }) => !!isActive)
            if (options.length) {
              const group = {
                label: `${key}-${packageCode}--${slug}`,
                options
              }
              const ifBenefitPacketAlreadyExistIndex = benefitListInMultilevel.findIndex((b) => b.label === `${key}-${packageCode}--${slug}`)
              if (ifBenefitPacketAlreadyExistIndex === -1) {
                benefitListInMultilevel.push(group)
              } else {
                benefitListInMultilevel[ifBenefitPacketAlreadyExistIndex] = {
                  label: `${key}-${packageCode}--${slug}`,
                  options: [
                    ...(benefitListInMultilevel[ifBenefitPacketAlreadyExistIndex]?.options || []),
                    ...options
                  ]
                }
              }
            }
          })
        }
      }
    }
    return benefitListInMultilevel
  }

  return (
    <div>
      <Spin size='large' spinning={!!autoApprovalConfigDataLoading}>
        <FormContainer>
          <Form layout='inline' className='search-form' hideRequiredMark onReset={handleReset}>
            <Form.Item label='Provider' validateStatus={(productError || providerListError) ? 'error' : ''} help={productError || ''}>
              {getFieldDecorator('provider', {
                initialValue: selectedProvider ? JSON.stringify(selectedProvider) : undefined
              })(
                <Select
                  showSearch
                  style={{ width: 200 }}
                  placeholder='Select Provider'
                  onChange={handleSelectProvider}
                  dropdownMatchSelectWidth={false}
                  disabled={!!(configId && selectedProvider) || currentStepInConfig > 0}
                  loading={!!providerListLoading}
                  allowClear
                  filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                >
                  {
                    providerList && providerList.map((provider) => <Option key={provider.id} value={JSON.stringify(provider)}>{provider.name}</Option>)
                  }
                </Select>
              )}
            </Form.Item>
            <Form.Item label='Product' validateStatus={productError ? 'error' : ''} help={productError || ''}>
              {getFieldDecorator('product', {
                initialValue: selectedProduct ? selectedProduct.map((product) => JSON.stringify(product)) : undefined
              })(
                <Select
                  showSearch
                  mode='multiple'
                  style={{ width: 200 }}
                  placeholder='Select product'
                  onChange={handleSelectProduct}
                  dropdownMatchSelectWidth={false}
                  disabled={currentStepInConfig > 0}
                  allowClear
                  filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                >
                  {
                    productList && productList.map((product) => <Option key={product.id} value={JSON.stringify(product)}>{product.display_name}</Option>)
                  }
                </Select>
              )}
            </Form.Item>
            <Form.Item label='Benefit' validateStatus={packageError ? 'error' : ''} help={packageError || ''}>
              {getFieldDecorator('benefit', {
                initialValue: selectedBenefit ? selectedBenefit.map((benefit) => JSON.stringify(benefit)) : undefined
              })(
                <Select
                  showSearch
                  allowClear
                  style={{ width: 200 }}
                  placeholder='Select a benefit'
                  onChange={handleBenefitChange}
                  optionFilterProp='children'
                  dropdownMatchSelectWidth={false}
                  loading={!!(getPackageListLoading || getBenefitGroupLoading)}
                  disabled={currentStepInConfig > 0}
                  mode='multiple'
                  filterOption={(input, option) => {
                    const { children } = option.props
                    if (option.type.isSelectOptGroup) {
                      return children.includes(child => child.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0)
                    }
                    return children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                  }}
                  dropdownRender={menu => {
                    return (
                      <div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 10 }}>
                          <div
                            onClick={onSelectAllClicked}
                            style={{ width: 100, height: 10 }}
                            onMouseDown={e => e.preventDefault()}
                          >Select all
                          </div>
                        </div>
                        {menu}
                      </div>
                    )
                  }}
                >
                  {getBenfitListMultiple(benefitGroupData).map((benefitGroup) => {
                    const { label, options } = benefitGroup
                    return (
                      <OptGroup label={label} key={JSON.stringify(label)}>
                        {options.map(({ label, value }) => (
                          <Option value={value} key={label + '-' + value}>
                            {label}
                          </Option>))}
                      </OptGroup>
                    )
                  })}
                </Select>
              )}
            </Form.Item>
            <Form.Item>
              <Button type='danger' htmlType='reset' disabled={currentStepInConfig > 0}>
                Clear Filter
              </Button>
            </Form.Item>
          </Form>
        </FormContainer>
        {
          selectedProvider &&
            selectedProduct &&
            selectedBenefit &&
            Array.isArray(selectedBenefit) &&
            selectedBenefit.length &&
            claimConfigTemplate.length
            ? (
              <AddConfig
                productKey={selectedProduct}
                benefitId={selectedBenefit}
                provider={selectedProvider}
                configDumpData={configDumpData}
                configData={configData}
                stepChangeInTemplate={stepChangeInTemplate}
              />
              )
            : null
        }
      </Spin>
    </div>
  )
}

const mapSateToProps = (state) => ({
  productList: state.Insurance.products,
  claimConfigTemplate: state.Claims.claimConfigTemplate,
  benefitGroupData: state.Claims.benefitGroupData,
  getBenefitGroupError: state.Error.GET_BENEFIT_GROUP,
  getBenefitGroupLoading: state.Loading.GET_BENEFIT_GROUP_MULTIPLE_PRODUCT,
  providerList: state.Provider.providerList,
  packageList: state.Claims.packageListOnMultipleProduct,
  autoApprovalConfigData: state.Claims.autoApprovalConfigData,
  greenChannelConfigData: state.Claims.greenChannelConfigData,
  providerListLoading: state.Loading.GET_PROVIDER_LIST,
  providerListError: state.Error.GET_PROVIDER_LIST,
  autoApprovalConfigDataLoading: state.Loading.GET_AUTO_APPROVAL_CONFIG_INFO,
  getPackageListLoading: state.Loading.GET_PACKAGE_MULTIPLE_PRODUCT_LIST
})

const mapDispatchToProps = {
  getProducts,
  getConfigTemplates,
  getGreenChannelData,
  resetReduxStateClaim,
  getProviderList,
  getPackageMultipleProduct,
  getAutoApprovalConfigInfo,
  getMultipleProductBenefitList,
  getPolicyFormAttributesMultipleProduct
}

const AddInstantClaimConfigurationContainer = connect(mapSateToProps, mapDispatchToProps)(Form.create()(AddInstantClaimConfiguration))

export default AddInstantClaimConfigurationContainer
